// streamInfLines returns the master's EXT-X-STREAM-INF lines, in order.
func streamInfLines(master string) []string {
	var out []string
	for _, l := range strings.Split(master, "\n") {
		if strings.HasPrefix(l, "#EXT-X-STREAM-INF:") {
			out = append(out, l)
		}
	}
	return out
}

// mediaLines returns the master's EXT-X-MEDIA lines, in order.
func mediaLines(master string) []string {
	var out []string
	for _, l := range strings.Split(master, "\n") {
		if strings.HasPrefix(l, "#EXT-X-MEDIA:") {
			out = append(out, l)
		}
	}
	return out
}

// attrValue extracts a quoted attribute value ("NAME=\"x\"") from an HLS tag.
func attrValue(tag, attr string) string {
	i := strings.Index(tag, attr+`="`)
	if i < 0 {
		return ""
	}
	rest := tag[i+len(attr)+len(`="`):]
	j := strings.Index(rest, `"`)
	if j < 0 {
		return ""
	}
	return rest[:j]
}

// packWithVoiceovers packs an h264 fixture with two aac voiceovers into a
// fresh item under its own temp root and returns the published root master's
// bytes, the build directory, and the recorded codec record.
func packWithVoiceovers(t *testing.T, dur, head time.Duration) (master, buildDir string, codecs []string) {
	t.Helper()
	ctx := context.Background()
	dir := t.TempDir()
	fixture := makeH264Fixture(t, dir, dur)
	v1 := makeVoiceover(t, dir, "vo1.mka", 600, dur)
	v2 := makeVoiceover(t, dir, "vo2.mka", 800, dur)
	s := newTestService(t, filepath.Join(dir, "streams"), head)
	build, err := s.Pack(ctx, "it_m", fixture, map[string]any{"format": map[string]any{"duration": "12.0"}},
		[]string{v1, v2})
	if err != nil {
		t.Fatalf("Pack: %v", err)
	}
	buildDir = filepath.Join(s.Root, "it_m", build.Nonce)
	return readFile(t, filepath.Join(buildDir, "index.m3u8")), buildDir, build.Codecs
}

// TestMasterPlaylist is the spec floor for "Master playlist on every pack"
// (pack-manifest-audio 1.1, D1/D2): the lane composes the build root's master
// at the head-first publish — one video variant (CODECS when composable,
// BANDWIDTH, RESOLUTION when probed), the audio renditions ONLY as the
// EXT-X-MEDIA "aud" group with unique NAMEs and exactly one DEFAULT=YES —
// byte-identical for identical facts, complete at birth (the tail merge never
// rewrites it), ffmpeg's double-listed master never surviving to the
// published root, and an uncomposable codec record degrading the attributes,
// never the shape.
func TestMasterPlaylist(t *testing.T) {
	ctx := context.Background()

	t.Run("composed_shape_byte_identical_for_identical_facts", func(t *testing.T) {
		m1, dir1, codecs1 := packWithVoiceovers(t, 12*time.Second, 5*time.Second) // head 5s + tail 7s
		m2, _, codecs2 := packWithVoiceovers(t, 12*time.Second, 5*time.Second)    // identical inputs, fresh nonce
		if m1 != m2 {
			t.Fatalf("composed master is not byte-identical for identical facts:\nA:\n%s\nB:\n%s", m1, m2)
		}
		if len(codecs1) == 0 || len(codecs1) != len(codecs2) {
			t.Fatalf("codec records %v / %v, want equal non-empty records", codecs1, codecs2)
		}
		master := m1

		// The variant: exactly one EXT-X-STREAM-INF — the video rendition —
		// with the probed attributes and the composed CODECS.
		inf := streamInfLines(master)
		if len(inf) != 1 {
			t.Fatalf("master carries %d EXT-X-STREAM-INF lines, want exactly the one video variant:\n%s", len(inf), master)
		}
		for _, want := range []string{"BANDWIDTH=", "RESOLUTION=", `CODECS="avc1.`, `AUDIO="aud"`} {
			if !strings.Contains(inf[0], want) {
				t.Fatalf("variant line missing %q:\n%s", want, inf[0])
			}
		}
		// The variant's URI line follows its tag and names rend0.
		lines := strings.Split(master, "\n")
		for i, l := range lines {
			if l == inf[0] {
				if i+1 >= len(lines) || lines[i+1] != "rend0/index.m3u8" {
					t.Fatalf("variant line not followed by rend0/index.m3u8:\n%s", master)
				}
				break
			}
		}

		// The audio group: embedded (rend1) first, then the voiceovers;
		// unique NAMEs; exactly one DEFAULT=YES — the embedded audio; the
		// voiceovers selectable but never default.
		media := mediaLines(master)
		if len(media) != 3 {
			t.Fatalf("master carries %d EXT-X-MEDIA lines, want 3 (embedded + two voiceovers):\n%s", len(media), master)
		}
		names := map[string]bool{}
		defaults := 0
		for i, l := range media {
			if !strings.HasPrefix(l, `#EXT-X-MEDIA:TYPE=AUDIO,GROUP-ID="aud",NAME="`) {
				t.Fatalf("EXT-X-MEDIA line %d not an aud-group audio member:\n%s", i, l)
			}
			if !strings.Contains(l, `AUTOSELECT=YES`) || !strings.Contains(l, `URI="rend`) {
				t.Fatalf("EXT-X-MEDIA line %d missing AUTOSELECT/URI:\n%s", i, l)
			}
			name := attrValue(l, "NAME")
			if name == "" {
				t.Fatalf("EXT-X-MEDIA line %d carries no NAME:\n%s", i, l)
			}
			if names[name] {
				t.Fatalf("duplicate EXT-X-MEDIA NAME %q — NAMES must be unique:\n%s", name, master)
			}
			names[name] = true
			if strings.Contains(l, "DEFAULT=YES") {
				defaults++
				if i != 0 {
					t.Fatalf("EXT-X-MEDIA line %d defaults; only the embedded audio (line 0) may:\n%s", i, master)
				}
			}
		}
		if defaults != 1 {
			t.Fatalf("master carries %d DEFAULT=YES, want exactly one:\n%s", defaults, master)
		}

		// Complete at birth: the tail merge rewrote only the variant
		// playlists — the master references no t/ tree and carries no merge
		// markers, while rend0 does.
		if strings.Contains(master, "t/") || strings.Contains(master, "#EXT-X-DISCONTINUITY") ||
			strings.Contains(master, "#EXT-X-ENDLIST") {
			t.Fatalf("master was touched after birth (t/ ref, DISCONTINUITY, or ENDLIST):\n%s", master)
		}
		rend0 := readFile(t, filepath.Join(dir1, "rend0", "index.m3u8"))
		if !strings.Contains(rend0, "t/") || !strings.Contains(rend0, "#EXT-X-DISCONTINUITY") ||
			!strings.Contains(rend0, "#EXT-X-ENDLIST") {
			t.Fatalf("rend0 playlist missing the completed merge markers:\n%s", rend0)
		}
	})

	t.Run("uncomposable_record_degrades_attributes_not_shape", func(t *testing.T) {
		dir := t.TempDir()
		fixture := makeFixture(t, dir, 12*time.Second) // mpeg4 video: outside the composition table
		vo := makeVoiceover(t, dir, "vo.mka", 600, 12*time.Second)
		s := newTestService(t, filepath.Join(dir, "streams"), 600*time.Second) // head-only publish path
		build, err := s.Pack(ctx, "it_deg", fixture, map[string]any{"format": map[string]any{"duration": "12.0"}},
			[]string{vo})
		if err != nil {
			t.Fatalf("Pack: %v", err)
		}
		if build.Codecs != nil {
			t.Fatalf("Build.Codecs = %v, want nil (the record degrades, the pack still lands)", build.Codecs)
		}
		master := readFile(t, filepath.Join(s.Root, "it_deg", build.Nonce, "index.m3u8"))
		if strings.Contains(master, "CODECS") {
			t.Fatalf("degraded master still carries a CODECS attribute:\n%s", master)
		}
		if len(streamInfLines(master)) != 1 || !strings.Contains(master, "BANDWIDTH=") {
			t.Fatalf("degraded master lost the corrected shape (one variant with BANDWIDTH):\n%s", master)
		}
		if n := len(mediaLines(master)); n != 2 {
			t.Fatalf("degraded master carries %d EXT-X-MEDIA lines, want the embedded + voiceover group:\n%s", n, master)
		}
		if strings.Count(master, "DEFAULT=YES") != 1 {
			t.Fatalf("degraded master does not carry exactly one DEFAULT=YES:\n%s", master)
		}
	})

	t.Run("ffmpeg_master_never_survives_to_the_published_root", func(t *testing.T) {
		master, buildDir, _ := packWithVoiceovers(t, 12*time.Second, 5*time.Second) // head 5s + tail 7s
		// ffmpeg's generated shape is recognizable by its double-listing: one
		// STREAM-INF per rendition, AVERAGE-BANDWIDTH, its own group spelling.
		if strings.Contains(master, "AVERAGE-BANDWIDTH") || strings.Contains(master, "group_aud") {
			t.Fatalf("published root master is ffmpeg's, not the lane's composition:\n%s", master)
		}
		// The tail phase's own master copy is dropped before the move: nothing
		// unreferenced lands under t/.
		if _, err := os.Stat(filepath.Join(buildDir, "t", "index.m3u8")); err == nil {
			t.Fatal("ffmpeg's tail master survived into the published build under t/")
		}
		// The whole master still probes as playable media (the group resolves).
		kinds := streamKinds(probeStreams(t, filepath.Join(buildDir, "index.m3u8")))
		if kinds["video"] < 1 || kinds["audio"] < 1 {
			t.Fatalf("master probe streams = %v, want playable media", kinds)
		}
	})

	// The single-variant pack (the common case — no voiceovers) publishes the
	// same shape as a rendition build (pack-manifest-audio 1.2, D2/D3): the
	// build root holds ONLY the composed master whose one variant line carries
	// the muxed CODECS ("<video>,<audio>"), the variant tree under rend0/, and
	// the play URL keeps naming index.m3u8 — the spec scenarios "Single-variant
	// pack serves a master carrying the pack's codecs" and "Partial build
	// mounts with the master from the first byte".
	t.Run("single_variant_pack_publishes_the_composed_master", func(t *testing.T) {
		dir := t.TempDir()
		fixture := makeH264Fixture(t, dir, 12*time.Second)
		s := newTestService(t, filepath.Join(dir, "streams"), 5*time.Second) // head 5s + tail 7s: both phases run

		build, err := s.Pack(ctx, "it_sv", fixture, map[string]any{"format": map[string]any{"duration": "12.0"}}, nil)
		if err != nil {
			t.Fatalf("Pack: %v", err)
		}
		if build.Playlist != mediaPrefix+"/it_sv/"+build.Nonce+"/index.m3u8" {
			t.Fatalf("Build.Playlist = %q, want the master's URL (index.m3u8 stays the play URL)", build.Playlist)
		}
		buildDir := filepath.Join(s.Root, "it_sv", build.Nonce)
		master := readFile(t, filepath.Join(buildDir, "index.m3u8"))

		// One variant line with the probed attributes and the muxed CODECS —
		// video first, audio second, no audio group on a group-less build.
		inf := streamInfLines(master)
		if len(inf) != 1 {
			t.Fatalf("single-variant master carries %d EXT-X-STREAM-INF lines, want one:\n%s", len(inf), master)
		}
		for _, want := range []string{"BANDWIDTH=", "RESOLUTION=", `CODECS="avc1.`} {
			if !strings.Contains(inf[0], want) {
				t.Fatalf("variant line missing %q:\n%s", want, inf[0])
			}
		}
		if strings.Contains(master, `AUDIO="`) || len(mediaLines(master)) != 0 {
			t.Fatalf("group-less master declares an audio group:\n%s", master)
		}
		codecs := strings.Split(attrValue(inf[0], "CODECS"), ",")
		if len(codecs) != 2 || !strings.HasPrefix(codecs[0], "avc1.") || codecs[1] != "mp4a.40.2" {
			t.Fatalf("CODECS = %q, want \"<avc1>,mp4a.40.2\" (video, muxed audio):\n%s", attrValue(inf[0], "CODECS"), master)
		}
		// The variant line references the media playlist beneath the root.
		lines := strings.Split(master, "\n")
		for i, l := range lines {
			if l == inf[0] {
				if i+1 >= len(lines) || lines[i+1] != "rend0/index.m3u8" {
					t.Fatalf("variant line not followed by rend0/index.m3u8:\n%s", master)
				}
				break
			}
		}
		// Complete at birth: the master stays static while rend0 carries the
		// merge markers, the init segment, and the segments.
		if strings.Contains(master, "t/") || strings.Contains(master, "#EXT-X-ENDLIST") {
			t.Fatalf("master was touched after birth (t/ ref or ENDLIST):\n%s", master)
		}
		rend0 := readFile(t, filepath.Join(buildDir, "rend0", "index.m3u8"))
		for _, want := range []string{"#EXT-X-ENDLIST", "#EXT-X-DISCONTINUITY", "init.mp4", "t/rend0/"} {
			if !strings.Contains(rend0, want) {
				t.Fatalf("rend0 playlist missing %q:\n%s", want, rend0)
			}
		}
		// The partial build mounted with the same master: nothing about the
		// completed bytes distinguishes the composition moment (D2).
		if err := s.ValidateBuild("it_sv", build.Nonce); err != nil {
			t.Fatalf("ValidateBuild(single-variant master build) = %v, want nil", err)
		}
		// The master still probes as playable media (hls.js's whole load path).
		kinds := streamKinds(probeStreams(t, filepath.Join(buildDir, "index.m3u8")))
		if kinds["video"] != 1 || kinds["audio"] != 1 {
			t.Fatalf("master probe streams = %v, want the video + muxed audio", kinds)
		}
	})

	t.Run("single_variant_head_only_publishes_the_same_shape_atomically", func(t *testing.T) {
		dir := t.TempDir()
		fixture := makeH264Fixture(t, dir, 12*time.Second)
		s := newTestService(t, filepath.Join(dir, "streams"), 600*time.Second) // the whole file IS the head chunk

		build, err := s.Pack(ctx, "it_svh", fixture, map[string]any{"format": map[string]any{"duration": "12.0"}}, nil)
		if err != nil {
			t.Fatalf("Pack: %v", err)
		}
		buildDir := filepath.Join(s.Root, "it_svh", build.Nonce)
		master := readFile(t, filepath.Join(buildDir, "index.m3u8"))
		inf := streamInfLines(master)
		if len(inf) != 1 || !strings.Contains(inf[0], `CODECS="avc1.`) || !strings.Contains(master, "rend0/index.m3u8") {
			t.Fatalf("head-only build root is not the composed master:\n%s", master)
		}
		rend0 := readFile(t, filepath.Join(buildDir, "rend0", "index.m3u8"))
		if !strings.Contains(rend0, "#EXT-X-ENDLIST") || strings.Contains(rend0, "#EXT-X-DISCONTINUITY") {
			t.Fatalf("head-only rend0 playlist is not the finalized head:\n%s", rend0)
		}
		if err := s.ValidateBuild("it_svh", build.Nonce); err != nil {
			t.Fatalf("ValidateBuild(head-only single-variant) = %v, want nil", err)
		}
	})

	// The attribute-less degradation (spec scenario "Uncomposable codecs keep
	// the corrected master shape") holds for the single-variant master too:
	// the pack lands, the root still serves the composed shape, the CODECS
	// attribute alone drops.
	t.Run("single_variant_uncomposable_record_degrades_attributes_not_shape", func(t *testing.T) {
		dir := t.TempDir()
		fixture := makeFixture(t, dir, 12*time.Second) // mpeg4 video: outside the composition table
		s := newTestService(t, filepath.Join(dir, "streams"), 600*time.Second)

		build, err := s.Pack(ctx, "it_svd", fixture, map[string]any{"format": map[string]any{"duration": "12.0"}}, nil)
		if err != nil {
			t.Fatalf("Pack: %v", err)
		}
		if build.Codecs != nil {
			t.Fatalf("Build.Codecs = %v, want nil (the record degrades, the pack still lands)", build.Codecs)
		}
		master := readFile(t, filepath.Join(s.Root, "it_svd", build.Nonce, "index.m3u8"))
		if strings.Contains(master, "CODECS") {
			t.Fatalf("degraded master still carries a CODECS attribute:\n%s", master)
		}
		inf := streamInfLines(master)
		if len(inf) != 1 || !strings.Contains(inf[0], "BANDWIDTH=") || !strings.Contains(master, "rend0/index.m3u8") {
			t.Fatalf("degraded master lost the corrected shape (one variant with BANDWIDTH over rend0):\n%s", master)
		}
		if err := s.ValidateBuild("it_svd", build.Nonce); err != nil {
			t.Fatalf("ValidateBuild(degraded single-variant) = %v, want nil", err)
		}
	})
}
